// Extract and validate VAPI call data
const items = $input.all();
const callData = items[0].json;

// Extract call information
const extractedData = {
  call_id: callData.call?.id || 'unknown',
  phone_number: callData.call?.phoneNumberId || callData.phoneNumber,
  customer_number: callData.call?.customer?.number || callData.customer?.number,
  transcript: callData.transcript || '',
  assistant_message: callData.message?.content || '',
  call_status: callData.call?.status || 'unknown',
  timestamp: new Date().toISOString(),

  // Extract healthcare search intent from transcript or assistant message
  search_query: callData.message?.content || callData.transcript || '',

  // VAPI function call data if present
  function_call: callData.message?.function_call || null,

  // Call metadata
  call_duration: callData.call?.duration || 0,
  call_direction: callData.call?.type || 'inbound'
};

// Log the received data for debugging
console.log('VAPI Call Data Received:', JSON.stringify(extractedData, null, 2));

return [{ json: extractedData }];

// Premier Health Voice Tools Integration
// This code integrates with the Premier Health voice agent tools

const items = $input.all();
const callData = items[0].json;

// Import Premier Health tools configuration
const DB_CONFIG = {
  host: 'localhost',
  port: 5432,
  database: 'community',
  user: 'postgres',
  password: 'aawwER44444'
};

// Extract search parameters from VAPI function call
let searchQuery = '';
let maxResults = 5;
let location = null;
let specialty = null;
let providerType = null;

if (callData.function_call) {
  const params = callData.function_call.arguments;
  searchQuery = params.query || '';
  maxResults = params.max_results || 5;
  location = params.location || null;
  specialty = params.specialty || null;
  providerType = params.provider_type || null;
} else {
  // Fallback to transcript analysis
  searchQuery = callData.search_query || callData.transcript || '';
}

// Simple intent extraction for fallback
if (!location && !specialty && !providerType) {
  const query = searchQuery.toLowerCase();

  // Extract location hints
  const locationPatterns = {
    'accra': 'ACCRA CENTRAL',
    'madina': 'MADINA',
    'circle': 'CIRCLE',
    'tesano': 'KOKOMLEMLE',
    'east legon': 'LEGON',
    'korle-bu': 'ADABRAKA',
    'airport': 'AIRPORT RESIDENTIAL AREA'
  };

  for (const [pattern, area] of Object.entries(locationPatterns)) {
    if (query.includes(pattern)) {
      location = area;
      break;
    }
  }

  // Extract specialty hints
  const specialtyPatterns = {
    'eye': 'Ophthalmology',
    'children': 'Pediatrics',
    'pediatric': 'Pediatrics',
    'women': 'Obstetrics/Gynecology',
    'dental': 'Dental',
    'emergency': 'Emergency',
    'general': 'General Practice'
  };

  for (const [pattern, spec] of Object.entries(specialtyPatterns)) {
    if (query.includes(pattern)) {
      specialty = spec;
      break;
    }
  }

  // Extract provider type hints
  if (query.includes('hospital')) providerType = 'hospital';
  else if (query.includes('clinic')) providerType = 'clinic';
  else if (query.includes('pharmacy')) providerType = 'pharmacy';
}

// Prepare search parameters
const searchParams = {
  query: searchQuery,
  max_results: maxResults,
  location: location,
  specialty: specialty,
  provider_type: providerType,
  db_config: DB_CONFIG,
  call_id: callData.call_id,
  customer_number: callData.customer_number,
  timestamp: callData.timestamp
};

console.log('Healthcare Search Parameters:', JSON.stringify(searchParams, null, 2));

return [{ json: searchParams }];

// Format voice response for VAPI
const items = $input.all();
let providers = [];

// Handle both direct database results and API results
if (items.length > 0) {
  if (Array.isArray(items)) {
    providers = items.map(item => item.json);
  } else {
    providers = items[0].json.providers || items;
  }
}

const searchParams = $('Prepare Healthcare Search').first().json;
const callData = $('Extract VAPI Call Data').first().json;

// Generate voice-optimized response
let voiceResponse = '';
let confidence = 0.0;

if (providers.length === 0) {
  voiceResponse = "I couldn't find any healthcare providers matching your request. You might want to try a different location or service type. For emergencies, please call 193 immediately.";
  confidence = 0.0;
} else if (providers.length === 1) {
  const provider = providers[0];
  voiceResponse = `I found ${provider.name}, a ${provider.provider_type} in ${provider.area}.`;
  if (provider.specialties && provider.specialties.length > 0) {
    voiceResponse += ` They offer ${provider.specialties.join(', ')}.`;
  }
  if (provider.phone_primary) {
    voiceResponse += ` You can reach them at ${provider.phone_primary}.`;
  }
  if (provider.address) {
    voiceResponse += ` They are located at ${provider.address}.`;
  }
  confidence = 0.9;
} else {
  voiceResponse = `I found ${providers.length} options for you. `;

  // Add details for first 3 providers
  for (let i = 0; i < Math.min(3, providers.length); i++) {
    const provider = providers[i];
    voiceResponse += `${i + 1}. ${provider.name} in ${provider.area}`;
    if (provider.phone_primary) {
      voiceResponse += `, phone ${provider.phone_primary}`;
    }
    voiceResponse += '. ';
  }

  if (providers.length > 3) {
    voiceResponse += `And ${providers.length - 3} more options available.`;
  }

  confidence = Math.min(0.9, 0.5 + (providers.length * 0.1));
}

// Add emergency guidance if needed
if (searchParams.query && searchParams.query.toLowerCase().includes('emergency')) {
  voiceResponse += " For life-threatening emergencies, please call 193 or go to the nearest hospital immediately.";
}

// Prepare response for VAPI
const vapiResponse = {
  call_id: callData.call_id,
  providers: providers,
  total_found: providers.length,
  voice_response: voiceResponse,
  confidence: confidence,
  search_query: searchParams.query,
  location: searchParams.location,
  specialty: searchParams.specialty,
  timestamp: new Date().toISOString(),

  // VAPI-specific response format
  message: {
    type: "assistant",
    content: voiceResponse,
    function_call_result: {
      success: true,
      data: {
        providers: providers.slice(0, 5), // Limit to 5 for response size
        total_found: providers.length,
        confidence: confidence
      }
    }
  },

  // Continue conversation flag
  end_call: false,
  transfer_to_human: false
};

console.log('VAPI Response Generated:', JSON.stringify(vapiResponse, null, 2));

return [{ json: vapiResponse }];

